+
+        .topbar {
+          flex-direction: column;
+          align-items: flex-start;
+          padding-bottom: 1.5rem;
+        }
+
+        .hero-points {
+          grid-template-columns: 1fr;
+        }
+
+        .contact-card {
+          padding: 1.25rem;
+        }
+      }
+
+      @media (forced-colors: active) {
+        .contact-card,
+        .field-shell,
+        .hero-point,
+        .product-badge,
+        .eyebrow {
+          border: 1px solid CanvasText;
+        }
+
+        .submit-button {
+          border: 2px solid ButtonText;
+        }
+      }
