+    <div id="app"></div>
+    <script>
+      const state = {
+        values: {
+          fullName: "",
+          email: "",
+          phone: "",
+        },
+        errors: {},
+        statusMessage: "",
+      };
+
+      const fieldConfig = {
+        fullName: {
+          label: "Full name",
+          required: true,
+          autocomplete: "name",
+          type: "text",
+          placeholder: "Jordan Lee",
+          helperText: "",
+        },
+        email: {
+          label: "Email address",
+          required: true,
+          autocomplete: "email",
+          type: "email",
+          placeholder: "jordan@example.com",
+          helperText: "",
+        },
+        phone: {
+          label: "Phone number",
+          required: false,
+          autocomplete: "tel",
+          type: "tel",
+          placeholder: "+1 415 555 0123",
+          helperText: "Optional. Use numbers with spaces, dashes, or parentheses, for example +1 415 555 0123.",
+        },
+      };
+
+      function validateField(name, value) {
+        const trimmed = value.trim();
+
+        if (name === "fullName") {
+          if (!trimmed) {
+            return "Error: Enter your full name.";
+          }
+
+          if (trimmed.length < 2) {
+            return "Error: Enter your full name using at least 2 characters.";
+          }
+        }
+
+        if (name === "email") {
+          if (!trimmed) {
+            return "Error: Enter your email address.";
+          }
+
+          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+          if (!emailPattern.test(trimmed)) {
+            return "Error: Enter a valid email address, like name@example.com.";
+          }
+        }
+
+        if (name === "phone" && trimmed) {
+          const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
+          if (!phonePattern.test(trimmed)) {
+            return "Error: Enter a valid phone number using digits and optional spaces, dashes, or parentheses.";
+          }
+        }
+
+        return "";
+      }
+
+      function validateForm(values) {
+        return Object.keys(fieldConfig).reduce((errors, name) => {
+          const message = validateField(name, values[name]);
+          if (message) {
+            errors[name] = message;
+          }
+          return errors;
+        }, {});
+      }
+
+      function renderField(name) {
+        const config = fieldConfig[name];
+        const value = state.values[name];
+        const error = state.errors[name];
+        const helperId = config.helperText ? name + "-help" : "";
+        const errorId = name + "-error";
+        const describedBy = [helperId, error ? errorId : ""].filter(Boolean).join(" ");
+
+        return `
+          <div class="form-field">
+            <label class="field-label" for="${name}">
+              <span>${config.label}</span>
+              ${config.required ? '<span class="required-indicator" aria-hidden="true">*</span>' : '<span class="helper-text">(optional)</span>'}
+            </label>
+            <div class="field-shell ${error ? "invalid" : ""}">
+              <input
+                class="field-input"
+                id="${name}"
+                name="${name}"
+                type="${config.type}"
+                value="${escapeHtml(value)}"
+                placeholder="${config.placeholder}"
+                autocomplete="${config.autocomplete}"
+                ${config.required ? "required" : ""}
+                ${error ? 'aria-invalid="true"' : ""}
+                ${describedBy ? 'aria-describedby="' + describedBy + '"' : ""}
+                ${error ? 'aria-errormessage="' + errorId + '"' : ""}
+              />
+            </div>
+            ${config.helperText ? '<p class="helper-text" id="' + helperId + '">' + config.helperText + "</p>" : ""}
+            <p class="error-text" id="${errorId}" ${error ? "" : "hidden"}>${error || ""}</p>
+          </div>
+        `;
+      }
+
+      function App() {
+        return `
+          <a class="skip-link" href="#main-content">Skip to main content</a>
+          <div class="page-shell">
+            <header class="topbar">
+              <div class="brand">Acme Cloud</div>
+              <div class="product-badge">Support</div>
+            </header>
+            <main id="main-content" tabindex="-1">
+              <section class="hero-grid" aria-labelledby="page-title">
+                <div class="hero-copy">
+                  <div class="eyebrow">Priority help, without the wait</div>
+                  <h1 id="page-title">Contact our support team</h1>
+                  <p>
+                    Tell us how we can help and a product specialist will follow up with next steps.
+                    Use your full name and best email so we can reach you quickly.
+                  </p>
+                  <div class="hero-points">
+                    <div class="hero-point">
+                      <strong>Fast triage</strong>
+                      Every request is routed to the right team based on your details.
+                    </div>
+                    <div class="hero-point">
+                      <strong>Human follow-up</strong>
+                      We reply with practical guidance from a real support specialist.
+                    </div>
+                  </div>
+                </div>
+                <section class="contact-card" aria-labelledby="form-title">
+                  <div class="card-header">
+                    <h2 id="form-title">Send a support request</h2>
+                    <p>Required fields are marked with <span class="required-indicator" aria-hidden="true">*</span>.</p>
+                    <p class="required-note">We only use these details to respond to your support request.</p>
+                  </div>
+                  <form id="support-form" novalidate>
+                    ${renderField("fullName")}
+                    ${renderField("email")}
+                    ${renderField("phone")}
+                    <div class="actions">
+                      <button class="submit-button" type="submit">Send request</button>
+                    </div>
+                    <p class="${state.statusMessage ? "success-text" : "helper-text"}" id="form-status" aria-live="polite">
+                      ${state.statusMessage || "Your details stay private and are only shared with our support team."}
+                    </p>
+                  </form>
+                </section>
+              </section>
+            </main>
+          </div>
+        `;
+      }
+
+      function escapeHtml(value) {
+        return value
+          .replaceAll("&", "&amp;")
+          .replaceAll("<", "&lt;")
+          .replaceAll(">", "&gt;")
+          .replaceAll('"', "&quot;")
+          .replaceAll("'", "&#39;");
+      }
+
+      function renderApp() {
+        document.getElementById("app").innerHTML = App();
+        bindEvents();
+      }
+
+      function updateField(name, value) {
+        state.values[name] = value;
+        state.errors[name] = validateField(name, value);
+        state.statusMessage = "";
+        renderApp();
+      }
+
+      function focusFirstInvalidField() {
+        const firstInvalidName = Object.keys(fieldConfig).find((name) => state.errors[name]);
+        if (!firstInvalidName) {
+          return;
+        }
+
+        const field = document.getElementById(firstInvalidName);
+        if (field) {
+          field.focus();
+        }
+      }
+
+      function handleSubmit(event) {
+        event.preventDefault();
+        state.errors = validateForm(state.values);
+
+        if (Object.keys(state.errors).length > 0) {
+          state.statusMessage = "";
+          renderApp();
+          focusFirstInvalidField();
+          return;
+        }
+
+        state.statusMessage = "Thanks. Your support request is ready to be reviewed, and our team will reply soon.";
+        renderApp();
+        const main = document.getElementById("main-content");
+        if (main) {
+          main.focus();
+        }
+      }
+
+      function bindEvents() {
+        Object.keys(fieldConfig).forEach((name) => {
+          const input = document.getElementById(name);
+          if (!input) {
+            return;
+          }
+
+          input.addEventListener("input", (event) => {
+            updateField(name, event.target.value);
+          });
+
+          input.addEventListener("blur", (event) => {
+            state.errors[name] = validateField(name, event.target.value);
+            renderApp();
+          });
+        });
+
+        const form = document.getElementById("support-form");
+        if (form) {
+          form.addEventListener("submit", handleSubmit);
+        }
+      }
+
+      renderApp();
+    </script>
+  </body>
+</html>
*** End Patch
', intention_summary=None, mcp_server_name=None, tool_title=None, type=<AssistantMessageToolRequestType.CUSTOM: 'custom'>)

