      const fieldConfig = {
        fullName: {
          label: "Full name",
          required: true,
          autocomplete: "name",
          type: "text",
          placeholder: "Jordan Lee",
          helperText: "",
        },
        email: {
          label: "Email address",
          required: true,
          autocomplete: "email",
          type: "email",
          placeholder: "jordan@example.com",
          helperText: "",
