        if (name === "phone" && trimmed) {
          const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
          if (!phonePattern.test(trimmed)) {
            return "Error: Enter a valid phone number using digits and optional spaces, dashes, or parentheses.";
