        document.getElementById("app").innerHTML = App();
        bindEvents();

        if (!focusState || !focusState.fieldId) {
          return;
        }

        const input = document.getElementById(focusState.fieldId);
        if (!input) {
          return;
        }

        input.focus();

        if (
          typeof focusState.selectionStart === "number" &&
          typeof focusState.selectionEnd === "number"
        ) {
          input.setSelectionRange(focusState.selectionStart, focusState.selectionEnd);
        }
      }

      function updateField(name, value) {
        state.values[name] = value;
        state.errors[name] = validateField(name, value);
        state.statusMessage = "";
        renderApp();
      }

      function focusFirstInvalidField() {
        const firstInvalidName = Object.keys(fieldConfig).find((name) => state.errors[name]);
        if (!firstInvalidName) {
          return;
        }

        const field = document.getElementById(firstInvalidName);
        if (field) {
          field.focus();
        }
      }

