               <div class="brand">Acme Cloud</div>
               <div class="product-badge">Support</div>
             </header>
             <main id="main-content" tabindex="-1">
               <section class="hero-grid" aria-labelledby="page-title">
                 <div class="hero-copy">
                   <div class="eyebrow">Priority help, without the wait</div>
                   <h1 id="page-title">Contact our support team</h1>
                   <p>
                     Tell us how we can help and a product specialist will follow up with next steps.
                     Use your full name and best email so we can reach you quickly.
                   </p>
                   <div class="hero-points">
                     <div class="hero-point">
                       <strong>Fast triage</strong>
                       Every request is routed to the right team based on your details.
                     </div>
                     <div class="hero-point">
                       <strong>Human follow-up</strong>
                       We reply with practical guidance from a real support specialist.
                     </div>
                   </div>
                 </div>
                 <section class="contact-card" aria-labelledby="form-title">
                   <div class="card-header">
                     <h2 id="form-title">Send a support request</h2>
                     <p>Required fields are marked with <span class="required-indicator" aria-hidden="true">*</span>.</p>
                     <p class="required-note">We only use these details to respond to your support request.</p>
                   </div>
                   <form id="support-form" novalidate>
                     ${renderField("fullName")}
                     ${renderField("email")}
                     ${renderField("phone")}
                     <p class="helper-text">Your details stay private and are only shared with our support team.</p>
                     <div class="actions">
                       <button class="submit-button" type="submit">Send request</button>
                     </div>
                     <p class="status-text ${state.statusMessage ? "success-text" : ""}" id="form-status" role="status" aria-live="polite">
                       ${state.statusMessage}
                     </p>
                   </form>
                 </section>
               </section>
             </main>
           </div>
         `;
       }

       function escapeHtml(value) {
         return value
           .replaceAll("&", "&amp;")
           .replaceAll("<", "&lt;")
           .replaceAll(">", "&gt;")
           .replaceAll('"', "&quot;")
           .replaceAll("'", "&#39;");
       }

       function renderApp(focusState = null) {
         document.getElementById("app").innerHTML = App();
         bindEvents();

         if (!focusState || !focusState.fieldId) {
           return;
         }

         const input = document.getElementById(focusState.fieldId);
         if (!input) {
           return;
         }

         input.focus();

         if (
           typeof focusState.selectionStart === "number" &&
           typeof focusState.selectionEnd === "number"
         ) {
           input.setSelectionRange(focusState.selectionStart, focusState.selectionEnd);
         }
       }

       function updateField(name, value) {
         state.values[name] = value;
         state.errors[name] = validateField(name, value);
         state.statusMessage = "";
       }

       function focusFirstInvalidField() {
         const firstInvalidName = Object.keys(fieldConfig).find((name) => state.errors[name]);
         if (!firstInvalidName) {
           return;
         }

         const field = document.getElementById(firstInvalidName);
         if (field) {
           field.focus();
         }
       }

       function handleSubmit(event) {
         event.preventDefault();
         state.errors = validateForm(state.values);

         if (Object.keys(state.errors).length > 0) {
           state.statusMessage = "";
           renderApp();
           focusFirstInvalidField();
           return;
         }

         state.statusMessage = "Thanks. Your support request is ready to be reviewed, and our team will reply soon.";
         renderApp();
       }

       function bindEvents() {
         Object.keys(fieldConfig).forEach((name) => {
           const input = document.getElementById(name);
           if (!input) {
             return;
           }

           input.addEventListener("input", (event) => {
             updateField(name, event.target.value);
             renderApp({
               fieldId: name,
               selectionStart: event.target.selectionStart,
               selectionEnd: event.target.selectionEnd,
             });
           });

           input.addEventListener("blur", (event) => {
             state.errors[name] = validateField(name, event.target.value);
             renderApp();
           });
         });

         const form = document.getElementById("support-form");
         if (form) {
           form.addEventListener("submit", handleSubmit);
         }
       }

       renderApp();
     </script>
   </body>
 </html>

